"""Optional AutoHotkey v2 export of the combo -> spare-key mapping (alternative to the built-in helper)."""
from __future__ import annotations

from datetime import datetime

from .keys import MODIFIERS, WHEEL_KEYS, Combo, ahk_name


def generate_ahk(proxies: dict[str, str], game_exe: str = "witcher3.exe") -> str:
    pre = {"Ctrl": "^", "Shift": "+", "Alt": "!"}
    lines = [
        "; Generated by W3 KeyBinder on " + datetime.now().strftime("%Y-%m-%d %H:%M"),
        "; Only needed if you prefer AutoHotkey v2 over W3 KeyBinder's built-in combo helper.",
        "#Requires AutoHotkey v2.0", "#SingleInstance Force", 'SendMode "Input"', "",
        "global Held := Map()",
        "Press(base, proxy) {", "    global Held", "    if Held.Has(base)", "        return",
        "    Held[base] := proxy", '    Send "{Blind}{" proxy " down}"', "}",
        "Release(base) {", "    global Held", "    if !Held.Has(base)", "        return",
        "    proxy := Held.Delete(base)", '    Send "{Blind}{" proxy " up}"', "}",
        "Tap(proxy) {", '    Send "{Blind}{" proxy " down}"', "    Sleep 30", '    Send "{Blind}{" proxy " up}"', "}",
        "", f'#HotIf WinActive("ahk_exe {game_exe}")',
    ]
    bases = {}
    for c in sorted(proxies):
        combo = Combo.parse(c)
        if combo.is_pad or combo.kind != "press":
            lines.append(f"; {c}: needs W3 KeyBinder's own helper (controller / hold / double-tap)")
            continue
        base, proxy = ahk_name(combo.key), ahk_name(proxies[c])
        custom = combo.custom_mods
        if len(custom) > 1 or (custom and any(m in combo.mods for m in MODIFIERS)):
            lines.append(f"; {c}: AutoHotkey can't do this combo (more than one held key), use W3 KeyBinder's helper")
            continue
        if custom:
            hk = f"{ahk_name(custom[0])} & {base}"   # custom held key: AutoHotkey "A & B" combo
        else:
            hk = "".join(pre[m] for m in MODIFIERS if m in combo.mods) + base
        lines.append(f"; {c}")
        if combo.key in WHEEL_KEYS:
            lines.append(f'{hk}::Tap("{proxy}")')
        else:
            lines.append(f'{hk}::Press("{base}", "{proxy}")')
            bases[base] = None
    lines += ["#HotIf", ""] + [f'~*{b} up::Release("{b}")' for b in bases] + [""]
    return "\r\n".join(lines)
